INSERT INTO `books` VALUES (18,'Umid uchquni','Remark',1,'\"[\\\"books\\\\/1746552390_0.jpg\\\"]\"','\"Umid uchquni\" – bu asar inson hayotidagi sinovlar, umidsizlik, orzular va irodaning kuchi haqida. Kitob qahramoni qanchalik og‘ir vaziyatlarga tushmasin, unda har doim bir umid uchquni bo‘lib, u hayotini davom ettirish, yengish va o‘z yo‘lini topishga turtki bo‘ladi. Asar o‘quvchini ruhiy jihatdan qo‘llab-quvvatlaydi va ichki kuchni uyg‘otishga chorlaydi.',54000,44000,'2026-04-13 13:01:06',1,'O‘zbek','Lotin','Qattiq',2025,300,1,1,0,1,13,572000,8,0,1,0,0,0,'[-0.019377679, 0.0040216134, 0.0050531025, 0.051419415, 0.023754053, 0.008770635, 0.001758897, 0.030956587, 0.0057745483, -0.024087945, -0.032149058, -0.029573318, -0.007554313, 0.002079374, 0.031338178, 0.03768213, 0.03942314, -0.0041527855, -0.010893237, 0.027951555, -0.005395938, 0.02129756, -0.024421837, 0.027236072, 0.031075833, 0.018328303, -0.017529346, -0.009611328, 0.00096217624, -0.010583194, 0.045719396, -0.02601975, 0.009366872, -0.00396199, -0.019151108, 0.036513507, 0.022215763, -0.029144028, 0.0000044950625, -0.0039023664, -0.035798024, -0.027498417, 0.008830259, -0.044193033, 0.017612819, -0.034223963, 0.0013743246, -0.013892305, 0.04426458, 0.001456307, -0.052802682, 0.0034432644, -0.010338737, 0.072645426, 0.032745294, -0.027927706, -0.03484405, 0.031218931, 0.012986026, 0.005491336, 0.013761133, -0.0520395, 0.021512205, 0.0116027575, 0.026258245, -0.03951854, -0.03732439, -0.012771381, -0.049082167, -0.023980623, 0.046530277, 0.081708215, 0.038039874, 0.011543134, 0.03129048, 0.013057574, -0.001890069, -0.065109, 0.0032345818, -0.0095636295, -0.023098193, 0.009891559, -0.0015174213, 0.020558227, -0.011131731, -0.018149432, -0.061340787, 0.008860071, -0.014297745, -0.021691075, -0.011435811, 0.03253065, -0.0014294764, -0.016491896, 0.04204658, -0.04903447, 0.03131433, -0.008323458, -0.058860444, -0.026830632, 0.00047959754, -0.01042221, 0.00024818335, 0.04023402, 0.06601528, -0.04917757, -0.054