iz ikki o\'rtada omtalash bo\'lgan odamlarmiz! Boshimizga nemis mushtlaganida o\'risga yukunib borardik, o\'ris do\'ppos-laganida nemisning oldiga yugurardik. Jadid munavvarlari bekorga \"o\'son millat\" demaganlar, Jamila!',60000,0,NULL,50,'uz','latin','hard',2025,350,1,55,0,1,0,0,1,0,1,0,0,0,'[0.015747216, 0.015879443, 0.0006006631, 0.05043917, -0.042721834, -0.025195545, -0.016480483, 0.041471675, 0.020868065, -0.060392372, -0.030508727, -0.057122722, 0.021120502, -0.01660069, 0.039235808, 0.083664596, -0.0064431354, -0.039812807, -0.014340784, 0.012429481, -0.017538311, 0.020819983, 0.003909757, -0.009814963, 0.038057774, 0.037528858, 0.004640019, -0.010055378, 0.04113509, -0.053612657, 0.04284204, -0.020543505, 0.036831655, -0.007945732, -0.012201087, -0.025796583, -0.014412909, -0.036062326, 0.0030863339, 0.009646672, -0.038658813, -0.008318376, 0.021204647, -0.027335241, 0.033417754, 0.025387876, -0.016949292, -0.035268955, 0.016684836, -0.018283598, -0.019798215, 0.018223494, -0.03880306, 0.05351649, 0.029426858, -0.04353925, -0.008474646, 0.015386592, 0.0013147723, -0.025027253, -0.029354732, -0.030268312, 0.019197177, 0.042385254, 0.009592579, -0.030268312, -0.014460992, -0.01954578, -0.029691314, 0.0010841236, 0.049862172, 0.013571455, 0.04938134, 0.03971664, 0.01163611, -0.019653967, 0.0065032393, -0.00070021016, 0.022995742, -0.0077533997, -0.043250747, 0.010115482, -0.037769273, 0.016384317, -0.002761773, 0.039283894, -0.07270165, -0.0033177338, 0.01862018, -0.059238378, -0.038394354, 0.037793316, -0.011143259, -0.002117159, 0.052987576, 0.043996036, 0.051977832, -0.026734203, -0.017249811, -0.048179265, -0.008877343, -0.039187726, 0.026734203, 0.008943456, 0.077317625, -0.051256586, -0.013691663, -0.034956414, -0.008564802, 0.0069540185, -0.077029124, -0.051112335, 0.029138358, 0.03925985, 0.065585345, -0.02637358, 0.058228634, 0.00007226552, -0.012886271, -0.050535336, 0.024137717, -0.012183055, -0.0021081434, 0.00044364174, -0.038899228, -0.00078135