INSERT INTO `market_news` VALUES (2,'blog/u64SjtF1qkF16xNTX5phUTHcLiWkQ7PtJEK4IOQX.jpg','Yetkazib berish','Blog emas','top',NULL,NULL,0,'2025-01-05 07:19:06','2026-02-26 12:48:24'),(3,'blog/j03RNVm5775zc9eDE6gePSupAGxn0z6j0sleYRtH.jpg','Bizing hamkor','Kitobchi loyihasini moliyaviy qo\'llab-quvvatlovchi universitet. Yaponiya bilimlarini endi O\'zbekistonda olishingiz mumkin, buning uchun Japan Digital University\'ni tanlang! Batafsil ma\'lumot uchun: www.jdu.uz','center',NULL,NULL,1,'2025-01-31 05:43:21','2026-02-25 21:40:55'),(6,'blog/VB19bn6lcti9eRnyRuCIAVJdef5THkcF3QgvhkHk.png','Yangi do\'kon','Endilikda Book.Uz do\'koni bilan hamkorlik yo\'lga qo\'yildi, kitoblar boshqalardan arzon narxda sotib olish uchun mavjud','center',NULL,NULL,1,'2025-12-13 20:52:34','2026-02-25 22:40:29');
